<?php require_once __DIR__.'/config/db.php'; startAppSession(); if(isLoggedIn()){ header('Location: '.url('dashboard.php')); exit; } $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL); $password=$_POST['password']??''; if($email && $password){ $q=getDB()->prepare("SELECT u.*,c.name club_name,c.tenant_status,c.trial_ends_at,c.currency_symbol,c.currency_code FROM users u JOIN clubs c ON c.id=u.club_id WHERE u.email=? AND u.is_active=1 LIMIT 1"); $q->execute([$email]); $u=$q->fetch(); if($u && password_verify($password,$u['password'])){ if($u['tenant_status']==='suspended'){ $error='This club workspace is suspended. Contact CuePOS support.'; }else{session_regenerate_id(true); $_SESSION=['user_id'=>$u['id'],'user_name'=>$u['name'],'user_role'=>$u['role'],'club_id'=>$u['club_id'],'club_name'=>$u['club_name'],'currency_symbol'=>$u['currency_symbol'] ?: 'Rs.','currency_code'=>$u['currency_code'] ?? 'PKR','is_platform_admin'=>(int)($u['is_platform_admin']??0),'csrf_token'=>bin2hex(random_bytes(32))]; $q=getDB()->prepare('UPDATE users SET last_login=NOW() WHERE id=?');$q->execute([$u['id']]); header('Location: '.url('dashboard.php'));exit;}} audit('login_failed','user',null,null,['email'=>$email]); if(!$error)$error='Invalid email or password.'; } else $error='Enter a valid email and password.'; } ?>
