v><?php endif; ?><label class="block mt-7 text-sm text-slate-300">Email<input required name="email" type="email" class="mt-2 w-full rounded-lg bg-slate-900 border border-slate-700 px-4 py-3 focus:outline-none focus:ring-2 focus:ring-[#0acb76]"></label><label class="block mt-5 text-sm text-slate-300">Password<div class="relative"><input required name="password" id="password" type="password" class="mt-2 w-full rounded-lg bg-slate-900 border border-slate-700 px-4 py-3 pr-12 focus:outline-none focus:ring-2 focus:ring-[#0acb76]"><button type="button" onclick="password.type=password.type==='password'?'text':'password'" class="absolute right-3 top-5 text-slate-400"><i class="fa-solid fa-eye"></i></button></div></label><button class="mt-7 w-full rounded-lg bg-[#0acb76] hover:bg-[#36db91] text-[#061420] py-3 font-bold">Sign in <i class="fa-solid fa-arrow-right ml-2"></i></button><p class="mt-7 text-center text-sm text-slate-400">New to CuePOS? <a class="text-[#0acb76] font-bold" href="<?=url('trial.php')?>">Start a free trial</a></p></form></main></div></body></html>
